(()=>{
'use strict';
const story=window.STORY, frames=story.frames, $=id=>document.getElementById(id);
const EPSILON=1e-4;
const choiceStates=new Map();
const total=frames.reduce((n,f)=>n+f.duration_sec,0);let time=0,index=-1,playing=false,raf=0,keyframeIndex=-1;
const format=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const starts=[];frames.reduce((n,f)=>{starts.push(n);return n+f.duration_sec},0);
const chapters=story.chapters||[{title:'01 · 打印一份惊喜',start_frame:0},{title:'02 · 足球场在哪边',start_frame:8},{title:'03 · 一起踢足球',start_frame:12}];
const chapterFor=i=>chapters.filter(c=>c.start_frame<=i).at(-1)||chapters[0];
function paragraph(text,cls,speaker){const p=document.createElement('p');if(cls)p.className=cls;if(speaker){const s=document.createElement('span');s.className='speaker';s.textContent=speaker;p.append(s)}p.append(document.createTextNode(text));return p}
let visualState='loading',imageGeneration=0,currentImageRequest=null,audioFailed=false,masterReady=false;
const imageCache=new Map(),imageRequests=new Map();
const imageUrl=k=>k.display_path||k.image_path;
function trimImageCache(){for(const [url,entry] of imageCache){if(imageCache.size<=6)break;if(url===$('frame').dataset.source)continue;URL.revokeObjectURL(entry.blobUrl);imageCache.delete(url)}}
async function fetchImage(url,signal){const r=await fetch(url,{signal,cache:'default'});if(!r.ok)throw Error('image response '+r.status);const blob=await r.blob();const bytes=new Uint8Array(await blob.slice(0,12).arrayBuffer());const webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!webp)throw Error('invalid display image');return new Blob([blob],{type:'image/webp'})}
function loadImage(url){if(imageCache.has(url))return Promise.resolve(imageCache.get(url));if(imageRequests.has(url))return imageRequests.get(url).promise;const control=new AbortController(),job={control};const timeout=setTimeout(()=>control.abort(),20000);job.promise=(async()=>{let blobUrl;try{const blob=await fetchImage(url,control.signal);if(control.signal.aborted)throw new DOMException('Aborted','AbortError');blobUrl=URL.createObjectURL(blob);const probe=new Image();probe.src=blobUrl;await probe.decode();if(control.signal.aborted)throw new DOMException('Aborted','AbortError');const entry={blobUrl};imageCache.set(url,entry);trimImageCache();return entry}catch(e){if(blobUrl)URL.revokeObjectURL(blobUrl);throw e}finally{clearTimeout(timeout);if(imageRequests.get(url)===job)imageRequests.delete(url)}})();imageRequests.set(url,job);return job.promise}
function prefetchNearby(){const f=frames[index],next=(f.keyframes||[]).slice(keyframeIndex+1,keyframeIndex+3);if(next.length<2&&frames[index+1])next.push(...frames[index+1].keyframes.slice(0,2-next.length));const current=imageUrl(f.keyframes[keyframeIndex]),wanted=new Set([current,...next.map(imageUrl)]);for(const [url,job]of imageRequests)if(!wanted.has(url)){job.control.abort();imageRequests.delete(url)}for(const k of next)loadImage(imageUrl(k)).catch(()=>{})}
async function showImage(a,f){const generation=++imageGeneration,url=imageUrl(a),picture=document.querySelector('.picture'),frame=$('frame');$('imageError').hidden=true;if(frame.dataset.source===url&&frame.complete&&frame.naturalWidth){visualState='ready';frame.alt=a.image_alt||f.title;picture.classList.remove('image-pending','first-image');$('imageLoading').hidden=true;prefetchNearby();return}for(const [other,job]of imageRequests)if(other!==url){job.control.abort();imageRequests.delete(other)}visualState='loading';picture.classList.add('image-pending');picture.classList.toggle('first-image',!frame.dataset.source);$('imageLoading').hidden=!!frame.dataset.source;const timer=setTimeout(()=>{if(generation===imageGeneration)$('imageLoading').hidden=false},180);try{const entry=await loadImage(url);if(generation!==imageGeneration)return;frame.src=entry.blobUrl;frame.dataset.source=url;frame.alt=a.image_alt||f.title;visualState='ready';picture.classList.remove('image-pending','first-image');$('imageLoading').hidden=true;trimImageCache();prefetchNearby()}catch(e){if(generation!==imageGeneration)return;console.warn('Story image load failed',url,String(e));visualState='error';$('imageLoading').hidden=true;$('imageError').hidden=false}finally{clearTimeout(timer)}}
function setKeyframe(k){const f=frames[index],ks=f.keyframes||[{at_sec:0,image_path:f.image_path,image_alt:f.image_alt,label:'画面'}];if(k===keyframeIndex)return;keyframeIndex=k;const a=ks[k];showImage(a,f);$('downloadFrame').href=a.image_path;$('downloadFrame').download=`${a.id||f.id}.png`;$('downloadComposite').hidden=!a.composite_path;if(a.composite_path){$('downloadComposite').href=a.composite_path;$('downloadComposite').download=`${a.id||f.id}-合成.png`;}document.querySelectorAll('#keyframes button').forEach((b,j)=>b.setAttribute('aria-current',String(j===k)))}

function renderFrame(i){index=i;keyframeIndex=-1;const f=frames[i];$('keyframes').replaceChildren();const ks=f.keyframes||[{at_sec:0,image_path:f.image_path,label:'画面'}];ks.forEach((k,j)=>{const b=document.createElement('button');b.type='button';b.textContent=(k.label||`${j+1}`)+(k.held_from?' · 停留':'');b.addEventListener('click',()=>{stop();seek(starts[index]+k.at_sec)});$('keyframes').append(b)});$('frameCount').textContent=`${String(i+1).padStart(2,'0')} / ${frames.length}`;$('chapter').textContent=chapterFor(i).nav_title||chapterFor(i).title;$('timeRange').textContent=`${format(starts[i])}—${format(starts[i]+f.duration_sec)}`;$('sceneTitle').textContent=f.title;const text=$('scriptText');text.replaceChildren();if(f.speech_segments?.length){for(const d of f.speech_segments){const line=paragraph(d.text,d.speaker==='旁白'?'narration':'dialogue',d.speaker);line.dataset.startSec=String(d.start_sec||0);text.append(line)}}else{if(f.narration)text.append(paragraph(f.narration,'narration','旁白'));for(const d of f.dialogues||[])text.append(paragraph(d.text,'dialogue',d.speaker))}$('previous').disabled=i===0;$('next').disabled=i===frames.length-1;document.querySelectorAll('.chapters button').forEach((b,j)=>b.setAttribute('aria-current',String(chapterFor(i)===chapters[j])));$('imageError').hidden=true;if(f.audio_path){$('audioStatus').textContent=f.audio_label||'中文合成配音 · 非原作演员';$('downloadAudio').hidden=false;$('downloadAudio').href=f.audio_path;$('downloadAudio').download=`${f.id}-配音.mp3`;}else{$('downloadAudio').hidden=true;}$('interaction').hidden=true;}
function renderOverlay(){const o=$('sceneOverlay'),f=frames[index],relative=time-starts[index];const currentKeyframe=f.keyframes?.[keyframeIndex]?.id;const overlay=(f.overlays||[]).find(o=>['three_choice','undecided_models_preview','time_jump_caption','physical_fork_clues','three_route_conjunction'].includes(o.type)&&(!o.visible_keyframe_ids||o.visible_keyframe_ids.includes(currentKeyframe))&&(o.type!=='time_jump_caption'||(relative>=o.display_at_sec&&relative<o.display_at_sec+o.duration_sec))&&(!['physical_fork_clues','three_route_conjunction'].includes(o.type)||relative+EPSILON>=o.reveal_at_sec));document.querySelector('.picture').classList.toggle('has-overlay',!!overlay);if(!overlay){o.hidden=true;o.replaceChildren();o.dataset.state='';return}o.hidden=false;const revealed=overlay.type==='three_choice'&&relative+EPSILON>=overlay.reveal_at_sec;const hot=decisionNow()?.p.kind==='model_choice';const state=`${f.id}:${keyframeIndex}:${revealed}:${hot}`;if(o.dataset?.state===state)return;o.replaceChildren();o.dataset.state=state;if(['time_jump_caption','physical_fork_clues','three_route_conjunction'].includes(overlay.type)){const img=document.createElement('img');img.className='full-overlay';img.src=overlay.type==='time_jump_caption'?story.time_jump_overlay_path:story.physical_route_overlay_path;img.alt=overlay.type==='time_jump_caption'?'过了一会儿':'这条路有小桥，桥后正好两棵树';o.append(img);return}if(overlay.type==='undecided_models_preview'){const img=document.createElement('img');img.className='tablet-models';img.src=story.model_strip_path;img.alt='平板上的小恐龙、足球奖杯和迷你赛车模型';const placement=f.keyframes?.[keyframeIndex]?.overlay_placement;if(placement)for(const key of ['left','top','width','height'])img.style[key]=placement[key]+'%';o.append(img);return}if(overlay.type==='three_choice'){const area=document.createElement('div');area.className='choice-area';const img=document.createElement('img');img.className='choice-models';img.src=story.model_strip_path;img.alt='小恐龙、足球奖杯、迷你赛车';area.append(img);o.append(area);const labels=document.createElement('img');labels.className='choice-label-layer';labels.src=story.choice_paths[revealed?'answer':'question'];labels.alt=revealed?'答案是B：足球奖杯':'A 小恐龙；B 足球奖杯；C 迷你赛车';o.append(labels);if(hot){const hits=document.createElement('div');hits.className='choice-hitarea';(decisionNow().p.choices||[]).forEach((value,i)=>{const b=document.createElement('button');b.type='button';b.className='choice-hit';b.setAttribute('aria-label','选择'+(typeof value==='string'?value:value.label));b.dataset.choice=String(i);b.addEventListener('click',()=>chooseOption(i));hits.append(b)});o.append(hits)}}}
function decisionNow(){const f=frames[index],relative=time-starts[index];const p=(f.pauses||[]).find(p=>p.interactive&&relative+EPSILON>=p.start_sec&&relative<p.start_sec+p.duration_sec-EPSILON);return p?{p,key:f.id+':'+(p.id||p.start_sec),relative}:null}
function decisionContinue(){const d=decisionNow(),state=d&&choiceStates.get(d.key);if(state){if(d.p.kind==='route_choice'&&!state.correct)return;const target=starts[index]+(d.p.resume_at_sec??d.p.reveal_at_sec??d.p.start_sec+d.p.duration_sec);seek(target);play();return}playing?stop():play()}
function chooseOption(choice){const d=decisionNow();if(!d)return;const correct=choice===d.p.answer_index;const previous=choiceStates.get(d.key)||{};choiceStates.set(d.key,{...previous,choice,correct,wrongAttempts:(previous.wrongAttempts||0)+(correct?0:1),feedbackMode:'choice'});stop();renderDecision()}
function requestHint(){const d=decisionNow();if(!d?.p.hints?.length)return;const previous=choiceStates.get(d.key)||{};choiceStates.set(d.key,{...previous,hintIndex:Math.min((previous.hintIndex??-1)+1,d.p.hints.length-1),feedbackMode:'hint'});stop();renderDecision()}
function routeFeedback(p,state){if(state.correct)return p.correct_feedback||'找到了！这条路两个线索都有。';if(state.feedbackMode==='hint')return p.hints?.[state.hintIndex]||p.wrong_choice_clue;if(state.wrongAttempts===1&&p.choice_hints?.[String(state.choice)])return p.choice_hints[String(state.choice)];return p.hints?.at(-1)||p.wrong_choice_clue||p.clue||'再看看两个线索。'}
function renderRouteClue(d){if(d?.p.kind!=='route_choice')return;const state=choiceStates.get(d.key);let mode='both';if(state&&!state.correct){if(state.feedbackMode==='hint')mode=['bridge','trees','both'][state.hintIndex]||'both';else if(state.wrongAttempts===1)mode=state.choice===0?'trees':state.choice===1?'bridge':'both'}const path=story.route_clue_paths?.[mode]||story.route_clues_path;if(path&&$('routeClueImage').getAttribute('src')!==path)$('routeClueImage').src=path;$('routeClueImage').alt=mode==='bridge'?'提示：找一找小桥':mode==='trees'?'提示：数一数，正好两棵树':'两个线索：小桥，以及桥后正好两棵树'}
function renderRouteTargets(){document.querySelector('.picture').classList.toggle('has-route-puzzle',(frames[index].overlays||[]).some(o=>o.type==='three_route_conjunction'));const target=$('routeTargets'),d=decisionNow();const regions=frames[index].keyframes?.[keyframeIndex]?.route_hit_regions||story.route_hit_regions;const active=d?.p.kind==='route_choice'&&regions?.length;if(!active){target.hidden=true;target.replaceChildren();target.dataset.key='';return}target.hidden=false;const key=d.key+':'+keyframeIndex;if(target.dataset.key!==key){target.replaceChildren();target.dataset.key=key;for(const region of regions){const b=document.createElement('button');b.type='button';b.className='route-hit';b.dataset.choice=String(region.choice_index);b.setAttribute('aria-label',d.p.choices[region.choice_index]);b.style.clipPath='polygon('+region.polygon.map(p=>(p[0]*100)+'% '+(p[1]*100)+'%').join(',')+')';b.addEventListener('click',()=>chooseOption(region.choice_index));target.append(b)}}const state=choiceStates.get(d.key);for(const b of target.children)b.setAttribute('aria-pressed',String(state?.choice===Number(b.dataset.choice)))}
function renderDecision(){const d=decisionNow(),wrapper=$('decisionChoices');$('interaction').hidden=!d;document.querySelector('.script').classList.toggle('has-decision',!!d);$('hintButton').hidden=!d?.p.hints?.length;$('routeClues').hidden=d?.p.kind!=='route_choice';wrapper.classList.toggle('route-options',d?.p.kind==='route_choice');$('play').disabled=false;$('continue').disabled=false;if(!d){wrapper.replaceChildren();wrapper.dataset.key='';$('choiceFeedback').hidden=true;$('choiceHint').hidden=true;$('playHint').textContent='自动播放，提问时会留出思考时间'}else{const {p,key}=d,state=choiceStates.get(key),supported=['model_choice','route_choice'].includes(p.kind);$('question').textContent=p.prompt;$('continue').textContent=state?'继续故事':playing?'暂停想一想':'继续故事';$('playHint').textContent=playing?'想一想，故事会在片刻后继续':'慢慢想，准备好后继续故事';$('choiceHint').hidden=!supported;$('hintButton').disabled=!!state?.correct;if(supported){if(wrapper.dataset.key!==key){wrapper.replaceChildren();wrapper.dataset.key=key;(p.choices||[]).forEach((value,i)=>{const b=document.createElement('button');b.type='button';const label=typeof value==='string'?value:value.label;if(p.kind==='route_choice'){b.setAttribute('aria-label',label);const arrow=document.createElement('span');arrow.className='route-arrow';arrow.setAttribute('aria-hidden','true');const paths=['M31 32L9 10M9 10H26M9 10V27','M20 34V6M20 6L8 18M20 6L32 18','M9 32L31 10M31 10H14M31 10V27'];arrow.innerHTML='<svg viewBox="0 0 40 40" width="32" height="32" focusable="false"><path d="'+paths[i]+'" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';b.append(arrow,document.createTextNode(label))}else b.textContent=label;b.addEventListener('click',()=>chooseOption(i));wrapper.append(b)})}Array.from(wrapper.children).forEach((b,i)=>b.setAttribute('aria-pressed',String(state?.choice===i)));document.querySelectorAll('.choice-hit,.route-hit').forEach(b=>b.setAttribute('aria-pressed',String(state?.choice===Number(b.dataset.choice))));$('choiceFeedback').hidden=!state;if(state){if(p.kind==='model_choice')$('choiceFeedback').textContent=p.continuation_notice||'记下你的选择啦。本故事继续打印足球奖杯。';else $('choiceFeedback').textContent=routeFeedback(p,state);$('hintButton').disabled=!!state.correct;const blocked=p.kind==='route_choice'&&!state.correct;$('continue').disabled=blocked;$('play').disabled=blocked;if(!playing&&!blocked)$('play').textContent='继续故事'}}else{wrapper.replaceChildren();wrapper.dataset.key='';$('choiceFeedback').hidden=true}}renderRouteClue(d);const f=frames[index],relative=time-starts[index];const protectedCue=(f.pauses||[]).find(p=>['model_choice','route_choice'].includes(p.kind));for(const el of $('scriptText').children){const at=Number(el.dataset.startSec||0),cue=protectedCue&&(protectedCue.reveal_at_sec??protectedCue.start_sec+protectedCue.duration_sec);el.hidden=!!protectedCue&&at>=cue-EPSILON&&relative<cue-EPSILON}}
function update(){const i=Math.min(frames.length-1,Math.max(0,starts.findLastIndex(s=>s<=time+EPSILON)));if(i!==index)renderFrame(i);const ks=frames[index].keyframes;if(ks?.length)setKeyframe(Math.max(0,ks.findLastIndex(k=>k.at_sec<=time-starts[index]+EPSILON)));renderOverlay();renderRouteTargets();const currentKey=frames[index].keyframes?.[keyframeIndex];$('frameCount').textContent=`${String(index+1).padStart(2,'0')} / ${frames.length}`+(currentKey?.held_from?' · 停留画面':'');$('timeline').value=time;$('elapsed').textContent=format(time>=total?Math.round(total):time);$('play').textContent=playing?'暂停':time>=total?'再看一遍':'播放故事';renderDecision();if(!masterReady&&!audioFailed){$('play').disabled=true;$('play').textContent='正在准备配音…'}document.querySelector('.picture').classList.toggle('is-playing',playing)}
const media=$('audio');let pendingSeek=null,playIntent=0;
media.preload='auto';let masterPromise=null;
function ensureMaster(){if(masterPromise)return masterPromise;masterPromise=(async()=>{const response=await fetch(story.master_audio_path,{cache:'default'});if(!response.ok)throw Error('audio response '+response.status);const bytes=await response.arrayBuffer();const head=new Uint8Array(bytes,0,Math.min(3,bytes.byteLength));if(bytes.byteLength!==story.master_audio_bytes||!(String.fromCharCode(...head)==='ID3'||(head[0]===255&&(head[1]&224)===224)))throw Error('invalid master audio');await new Promise((resolve,reject)=>{media.addEventListener('loadedmetadata',resolve,{once:true});media.addEventListener('error',reject,{once:true});media.src=URL.createObjectURL(new Blob([bytes],{type:'audio/mpeg'}));media.load()});masterReady=true;audioFailed=false;$('audioStatus').textContent=mediaLabel();update()})();masterPromise.catch(()=>{masterPromise=null});return masterPromise}

function mediaLabel(){return frames[index]?.audio_label||'普通话合成配音，非原作演员声音'}
function syncFromMedia(){if(pendingSeek!==null||media.seeking||media.readyState<1)return;time=Math.min(total,Math.max(0,media.currentTime));update()}
function stop(){++playIntent;playing=false;cancelAnimationFrame(raf);raf=0;syncFromMedia();media.pause();update()}
function finish(){++playIntent;pendingSeek=null;playing=false;cancelAnimationFrame(raf);raf=0;media.pause();time=total;update();$('playHint').textContent='故事讲完啦，要不要再看一遍？'}
function tick(){raf=0;if(!playing)return;syncFromMedia();if(media.ended||time>=total-EPSILON){finish();return}raf=requestAnimationFrame(tick)}
function startLoop(){cancelAnimationFrame(raf);raf=requestAnimationFrame(tick)}
function applyPendingSeek(){if(pendingSeek===null||media.readyState<1)return;const target=pendingSeek;media.currentTime=target;pendingSeek=null}
function play(){if(playing)return;const d=decisionNow(),state=d&&choiceStates.get(d.key);if(state&&d.p.kind==='route_choice'&&!state.correct)return;if(time>=total-EPSILON){choiceStates.clear();seek(0)}const intent=++playIntent;playing=true;if(audioFailed){audioFailed=false;pendingSeek=time}applyPendingSeek();update();startLoop();ensureMaster().then(()=>{if(intent!==playIntent||!playing)return;applyPendingSeek();return media.play()}).catch(error=>{if(intent!==playIntent)return;playing=false;cancelAnimationFrame(raf);raf=0;audioFailed=true;$('audioStatus').textContent='配音未能播放，请点播放重试';update()})}
function seek(t){const wasPlaying=playing;stop();time=Math.min(total,Math.max(0,t));pendingSeek=time;applyPendingSeek();update();if(wasPlaying&&time<total)play()}
media.addEventListener('loadedmetadata',()=>{applyPendingSeek();update()});
media.addEventListener('seeked',()=>{syncFromMedia()});
media.addEventListener('ended',()=>{if(media.ended&&pendingSeek===null)finish()});
media.addEventListener('waiting',()=>{if(playing)$('audioStatus').textContent='配音正在缓冲，请稍等…'});
media.addEventListener('playing',()=>{$('audioStatus').textContent=mediaLabel()});
media.addEventListener('error',()=>{audioFailed=true;stop();$('audioStatus').textContent='配音未能加载，请点播放重试'});
for(const name of ['loadstart','seeking','seeked','waiting','playing','ended'])media.addEventListener(name,()=>{media.dataset[name+'Count']=String(Number(media.dataset[name+'Count']||0)+1)});
$('play').addEventListener('click',()=>{const d=decisionNow();if(!playing&&d&&choiceStates.has(d.key))decisionContinue();else playing?stop():play()});$('continue').addEventListener('click',decisionContinue);$('hintButton').addEventListener('click',requestHint);$('previous').addEventListener('click',()=>seek(starts[Math.max(0,index-1)]));$('next').addEventListener('click',()=>seek(starts[Math.min(frames.length-1,index+1)]));$('timeline').max=total;$('timeline').addEventListener('input',e=>seek(Number(e.target.value)));$('total').textContent=format(Math.round(total));$('retryImage').addEventListener('click',()=>showImage(frames[index].keyframes[keyframeIndex],frames[index]));chapters.forEach(c=>{const b=document.createElement('button');b.type='button';b.textContent=c.nav_title||c.title;b.addEventListener('click',()=>seek(starts[c.start_frame]));$('chapters').append(b)});document.addEventListener('keydown',e=>{if(['INPUT','BUTTON','A'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();const d=decisionNow();if(!playing&&d&&choiceStates.has(d.key))decisionContinue();else playing?stop():play()}else if(e.code==='ArrowLeft'){e.preventDefault();seek(starts[Math.max(0,index-1)])}else if(e.code==='ArrowRight'){e.preventDefault();seek(starts[Math.min(frames.length-1,index+1)])}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)stop()});function openHash(){const id=location.hash.slice(1);const i=frames.findIndex(f=>f.id===id);if(i>=0){stop();seek(starts[i])}}window.addEventListener('hashchange',openHash);update();openHash();ensureMaster().catch(()=>{audioFailed=true;update();$('audioStatus').textContent='配音准备失败，请点播放重试'});
})();

/* Landscape stage: one media clock, same content, escapable native/fallback UI. */
(()=>{const shell=document.querySelector('.shell'),button=document.getElementById('fullscreen'),toggle=document.getElementById('stageControls'),hint=document.getElementById('orientationHint');let active=false,nativeStarted=false;
function viewport(){const v=window.visualViewport,w=v?.width||innerWidth,h=v?.height||innerHeight;document.documentElement.style.setProperty('--visible-height',h+'px');shell.style.setProperty('--viewer-width',w+'px');shell.style.setProperty('--viewer-height',h+'px');shell.classList.toggle('stage-rotated',active&&h>w);}
function paint(on){active=on;shell.classList.toggle('is-immersive',on);shell.classList.remove('controls-hidden');document.body.classList.toggle('viewer-fullscreen',on);button.textContent=on?'退出全屏':'横屏全屏';button.setAttribute('aria-pressed',String(on));toggle.hidden=!on;hint.hidden=!on;toggle.textContent='收起控制';toggle.setAttribute('aria-expanded','true');viewport()}
async function leave(){active=false;try{screen.orientation?.unlock?.()}catch(_){}if(document.fullscreenElement){try{await document.exitFullscreen()}catch(_){}}nativeStarted=false;paint(false);button.focus({preventScroll:true})}
button.addEventListener('click',async()=>{if(active){await leave();return}paint(true);hint.textContent='横屏画面模式 · 可横放设备观看';if(document.documentElement.requestFullscreen&&document.fullscreenEnabled){try{await document.documentElement.requestFullscreen();nativeStarted=true;if(!active){try{await document.exitFullscreen()}catch(_){}nativeStarted=false;return;}if(screen.orientation?.lock){try{await screen.orientation.lock('landscape');hint.textContent='横屏画面播放'}catch(_){hint.textContent='请横放设备；当前使用横向舞台布局'}}}catch(_){hint.textContent='当前浏览器使用横向舞台布局，可横放设备观看'}}else hint.textContent='当前浏览器使用横向舞台布局，可横放设备观看';viewport()});
toggle.addEventListener('click',()=>{const hidden=shell.classList.toggle('controls-hidden');toggle.textContent=hidden?'显示控制':'收起控制';toggle.setAttribute('aria-expanded',String(!hidden))});
document.addEventListener('fullscreenchange',()=>{if(nativeStarted&&!document.fullscreenElement){nativeStarted=false;paint(false)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();leave()}});window.addEventListener('resize',viewport);window.visualViewport?.addEventListener('resize',viewport);screen.orientation?.addEventListener('change',viewport);viewport();
})();
